// Extrai ID do Deal de webhook ONCRMDEALADD ou lista do polling
const items = $input.all();
const ids = [];

for (const item of items) {
  const json = item.json;
  const body = json.body || json;

  // Polling: array em json.result
  if (json.result && Array.isArray(json.result)) {
    for (const d of json.result) {
      if (d.ID) ids.push(Number(d.ID));
    }
  }
  // Webhook ONCRMDEALADD (URL encoded ou JSON)
  else {
    let dId = null;
    if (body['data[FIELDS][ID]']) dId = Number(body['data[FIELDS][ID]']);
    else if (body.data?.FIELDS?.ID) dId = Number(body.data.FIELDS.ID);
    else if (body.FIELDS?.ID) dId = Number(body.FIELDS.ID);
    else if (body.id || body.ID) dId = Number(body.id || body.ID);
    if (dId) ids.push(dId);
  }
}

// Deduplica IDs
const uniqueIds = [...new Set(ids)];
return uniqueIds.map(id => ({ json: { deal_id: id } }));

// GATE FAIL-CLOSED ABSOLUTO:
// Verifica se o Deal pertence EXCLUSIVAMENTE à Categoria 160 e ao usuário 32598 (Eduardo)
const items = $input.all();
const allowed = [];
const ALLOWED_REQUESTERS = [32598]; // Piloto restrito Eduardo Alaminos

for (const item of items) {
  const deal = item.json.result || item.json;
  const categoryId = String(deal.CATEGORY_ID || '');
  const stageId = String(deal.STAGE_ID || '');
  const createdBy = Number(deal.CREATED_BY_ID || 0);
  const title = deal.TITLE || `Chamado #${deal.ID}`;

  if (categoryId === '160' && stageId === 'C160:NEW' && ALLOWED_REQUESTERS.includes(createdBy)) {
    allowed.push({
      json: {
        deal_id: Number(deal.ID),
        title: title,
        requester_user_id: createdBy,
        requester_name: 'Eduardo Alaminos'
      }
    });
  }
}

return allowed;

